with.script:
const pr = context.payload.pull_request;
const labels = (pr.labels || []).map(l => l.name);

const fromLabel = labels.find(n => /^VUL-\d{4}-\d{4}$/.test(n));
const fromTrailer = (pr.body || '').match(/^GL-Vuln:\s*(VUL-\d{4}-\d{4})\b/im);
const vulId = fromLabel || (fromTrailer && fromTrailer[1]) || '';

const base = process.env.PATCH_REF;
const backports = [...new Set(
  labels
    .filter(n => /^backport\s+\S+/i.test(n))
    .map(n => n.replace(/^backport\s+/i, '').trim())
    .filter(b => b && b !== base)
)];
core.setOutput('vul_id', vulId);
core.setOutput('backport_refs', backports.join(' '));

await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: Number(process.env.PR_NUMBER),
  body: '🔐 No VUL ID found on this PR, so no security patch was generated. '
    + 'Add a `VUL-YYYY-NNNN` label or a `GL-Vuln: VUL-YYYY-NNNN` trailer to the description '
    + '(and any `backport <branch>` labels) to trigger patch creation.',
});

const {VUL_ID, BACKPORT_REFS, PATCH_REF, PR_NUMBER, RUN_URL} = process.env;
const targets = [PATCH_REF, ...(BACKPORT_REFS ? BACKPORT_REFS.split(' ') : [])];
// Link the exact triggered run when gh returned its URL; otherwise fall back
// to the workflow's runs page.
const runLink = RUN_URL
  ? `[run](${RUN_URL})`
  : '[security-patch-actions](https://github.com/grafana/security-patch-actions/actions/workflows/create-patch.yml)';
const body = [
  `🔐 **Security patch dispatched** for \`${VUL_ID}\``,
  '',
  `Targets: ${targets.map(t => `\`${t}\``).join(', ')}`,
  '',
  `Patch generation is running: ${runLink}. `
    + `The PR in \`grafana-security-patches\` will appear/update on branch \`patch/${VUL_ID}\` `
    + `(a link will be posted here once it's created).`,
].join('\n');
const comments = await github.paginate(github.rest.issues.listComments, {
  owner: context.repo.owner, repo: context.repo.repo, issue_number: Number(PR_NUMBER), per_page: 100,
});
for (const c of comments.filter(c => c.user.login === 'github-actions[bot]' && c.body.startsWith('🔐 **Security patch dispatched**'))) {
  await github.graphql('mutation($id: ID!) { minimizeComment(input: {subjectId: $id, classifier: OUTDATED}) { clientMutationId } }', {id: c.node_id});
}
await github.rest.issues.createComment({
  owner: context.repo.owner, repo: context.repo.repo, issue_number: Number(PR_NUMBER), body,
});

