steps.run:
gh pr diff "$PR_NUMBER" --repo "$REPO" | awk '
  /^diff --git/ { print; next }
  /^index / { print; next }
  /^---/ { print; next }
  /^\+\+\+/ { print; next }
  /^Binary files / { print; next }
  /^@@/ {
    split($2, old_parts, ",")
    split($3, new_parts, ",")
    old_line = -old_parts[1]
    new_line = substr(new_parts[1], 2)
    print
    next
  }
  /^-/ { printf "[OLD:%d]%s\n", old_line++, $0; next }
  /^\+/ { printf "[NEW:%d]%s\n", new_line++, $0; next }
  { printf "[OLD:%d,NEW:%d]%s\n", old_line++, new_line++, $0 }
' | head -10000 > pr_diff.txt
echo "Diff size: $(wc -l < pr_diff.txt) lines"
gh pr view "$PR_NUMBER" --repo "$REPO" --json body --jq '.body // "No description provided."' > pr_description.txt
PR_TITLE=$(gh pr view "$PR_NUMBER" --repo "$REPO" --json title --jq '.title')
echo "PR title: $PR_TITLE"
# Emit via a random-delimiter heredoc so titles with special
# characters are captured verbatim as a single step output.
DELIM="ghaout_$(openssl rand -hex 16)"
{
  printf 'pr_title<<%s\n' "$DELIM"
  printf '%s\n' "$PR_TITLE"
  printf '%s\n' "$DELIM"
} >> "$GITHUB_OUTPUT"

with.script:
let run = true;
if (context.payload.pull_request.user.login === 'renovate-sh-app[bot]') {
  // Renovate applies labels after opening the PR, so read the current labels.
  const { data: pullRequest } = await github.rest.pulls.get({
    ...context.repo,
    pull_number: context.issue.number,
  });
  run = pullRequest.labels.some((label) => label.name === 'ci/meticulous');
}
core.setOutput('run', run);

const {HEAD_REF, BASE_REF, REPO, SENDER, SHA, PR_COMMIT_SHA} = process.env;

await github.rest.actions.createWorkflowDispatch({
    owner: 'grafana',
    repo: 'security-patch-actions',
    workflow_id: 'test-patches-event.yml',
    ref: 'main',
    inputs: {
      src_repo: REPO,
      src_ref: HEAD_REF,
      src_merge_sha: SHA,
      src_pr_commit_sha: PR_COMMIT_SHA,
      patch_repo: REPO + '-security-patches',
      patch_ref: BASE_REF,
      triggering_github_handle: SENDER
    }
})

const {HEAD_REF, REPO} = process.env;

const maxWaitMs = 10 * 60 * 1000;
const pollIntervalMs = 15 * 1000;
const startTime = Date.now();
// Include a 60s lookback buffer to cover the time spent in the dispatch step.
const createdAfter = new Date(startTime - 60 * 1000).toISOString();

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

let runId = null;

while (true) {
  if (Date.now() - startTime >= maxWaitMs) {
    core.setFailed('Timed out after 10 minutes waiting for patch check to complete');
    return;
  }

  if (!runId) {
    const { data } = await github.rest.actions.listWorkflowRuns({
      owner: 'grafana',
      repo: 'security-patch-actions',
      workflow_id: 'test-patches-event.yml',
      branch: 'main',
      created: `>${createdAfter}`,
      per_page: 5,
    });

    const matchingRun = data.workflow_runs.find(
      run => run.name && run.name.includes(REPO) && run.name.includes(HEAD_REF)
    );
    if (matchingRun) {
      runId = matchingRun.id;
      console.log(`Dispatched workflow run: ${matchingRun.html_url}`);
    } else {
      await sleep(pollIntervalMs);
      continue;
    }
  }

  const { data: run } = await github.rest.actions.getWorkflowRun({
    owner: 'grafana',
    repo: 'security-patch-actions',
    run_id: runId,
  });

  if (run.status === 'completed') {
    if (run.conclusion === 'success') {
      return;
    }
    core.setFailed(`Patch check failed (conclusion: ${run.conclusion})`);
    return;
  }

  await sleep(pollIntervalMs);
}

let run = true;
const author = context.payload.head_commit?.author?.name;
if (context.eventName === 'push' && author === 'renovate-sh-app[bot]') {
  // Preserve the Renovate classification after its PR has been merged.
  const { data: pullRequests } = await github.rest.repos.listPullRequestsAssociatedWithCommit({
    ...context.repo,
    commit_sha: context.sha,
  });
  run = pullRequests.some((pullRequest) =>
    pullRequest.labels.some((label) => label.name === 'ci/meticulous')
  );
}
core.setOutput('run', run);

const {REF, VERSION, BUILD_ID, BUCKET, GRAFANA_COMMIT, PUBLIC_COMMIT, SOURCE_EVENT, REPO} = process.env;
// grafana-enterprise has no #patched branches, so dispatch it on the plain
// release branch (e.g. release-13.0.0#patched -> release-13.0.0).
let enterpriseRef = REF.replace(/#patched$/, '');

let workflow = 'release-build-enterprise.yml';

if (REF == 'main' && SOURCE_EVENT == 'push') {
  workflow = 'release-build-pro.yml';
}

if (SOURCE_EVENT == 'schedule') {
  workflow = 'release-build-nightly.yml';
}

const inputs = {
  "version": VERSION,
  "build-id": String(BUILD_ID),
  "bucket": BUCKET,
  "grafana-commit": GRAFANA_COMMIT,
  "source-event": SOURCE_EVENT,
  "upstream": REPO,
};
// Only release-build-enterprise.yml accepts (and stamps) the public commit;
// pro/nightly build from main where the stamped commit is already the HEAD.
if (workflow === 'release-build-enterprise.yml') {
  inputs["grafana-public-commit"] = PUBLIC_COMMIT;
  // Supply run ID separately in case we ever change what BUILD_ID is.
  // upstream-run-id is used with the github actions API and `gh run watch` to ensure coupled workflows
  // fail together.
  inputs["upstream-run-id"] = String(BUILD_ID);
}

// If the +security branch doesn't exist in grafana-enterprise yet, fall back to
// the base release branch (e.g. release-13.0.0+security-01 -> release-13.0.0).
// We probe by attempting the dispatch itself so no extra permission beyond
// actions:write is needed — a separate repos.getBranch call would require
// contents:read which the dispatch token does not have.
if (enterpriseRef.includes('+security-')) {
  try {
    await github.rest.actions.createWorkflowDispatch({
      owner: 'grafana',
      repo: 'grafana-enterprise',
      workflow_id: workflow,
      ref: enterpriseRef,
      inputs,
    });
    return;
  } catch (e) {
    // GitHub returns 422 "No ref found for <ref>" when the branch doesn't exist.
    if (e.status === 422 && String(e.message).includes('No ref found')) {
      const fallback = enterpriseRef.replace(/\+security-[0-9]+$/, '');
      core.info(`Enterprise branch ${enterpriseRef} not found; falling back to ${fallback}`);
      enterpriseRef = fallback;
    } else {
      throw e;
    }
  }
}

await github.rest.actions.createWorkflowDispatch({
    owner: 'grafana',
    repo: 'grafana-enterprise',
    workflow_id: workflow,
    ref:  enterpriseRef,
    inputs,
})

